17	import { breakpoints } from '../useBreakpoint';
18	import { utilityClassMap } from '../../utils/utilityClassMap';
19	import type { ComponentConfig, UnwrapResponsive, UtilityStyle } from './types';
20	
21	const namedBreakpoints = breakpoints.filter(b => b.id !== 'initial');
22	
23	function isResponsiveObject(value: unknown): value is Record<string, unknown> {
24	  return (
25	    typeof value === 'object' &&
26	    value !== null &&
27	    namedBreakpoints.some(b => b.id in value)
28	  );
29	}
30	
31	export function resolveResponsiveValue<T>(
32	  value: T,
33	  breakpoint: string,
34	): UnwrapResponsive<T> {
35	  if (!isResponsiveObject(value)) {
36	    return value as UnwrapResponsive<T>;
37	  }
38	
39	  const index = breakpoints.findIndex(b => b.id === breakpoint);
40	
41	  // Look for value at current breakpoint or smaller
42	  for (let i = index; i >= 0; i--) {
43	    const key = breakpoints[i].id;
44	    if (key in value && value[key] !== undefined) {
45	      return value[key] as UnwrapResponsive<T>;
46	    }
47	  }
48	
49	  // If no value found, check from smallest breakpoint up
50	  for (let i = 0; i < breakpoints.length; i++) {
51	    const key = breakpoints[i].id;
52	    if (key in value && value[key] !== undefined) {
53	      return value[key] as UnwrapResponsive<T>;
54	    }
55	  }
56	
57	  return value as UnwrapResponsive<T>;
58	}
59	
60	export function resolveDefinitionProps<D extends ComponentConfig<any, any>>(
61	  definition: D,
62	  props: Record<string, any>,
63	  breakpoint: string,
64	): {
65	  ownPropsResolved: Record<string, any>;
66	  restProps: Record<string, any>;
67	} {
68	  const ownPropKeys = new Set(Object.keys(definition.propDefs));
69	  const utilityPropKeys = new Set(definition.utilityProps ?? []);
70	
71	  const ownPropsRaw: Record<string, any> = {};
72	  const restProps: Record<string, any> = {};
73	
74	  for (const [key, value] of Object.entries(props)) {
75	    if (ownPropKeys.has(key)) {
76	      ownPropsRaw[key] = value;
77	    } else if (!(utilityPropKeys as Set<string>).has(key)) {
78	      restProps[key] = value;
79	    }
80	  }
81	
82	  const ownPropsResolved: Record<string, any> = {};
83	
84	  for (const [key, config] of Object.entries(definition.propDefs)) {
85	    const rawValue = ownPropsRaw[key];
86	    const resolvedValue = resolveResponsiveValue(rawValue, breakpoint);
87	    const finalValue = resolvedValue ?? (config as any).default;
88	    if (finalValue !== undefined) {
89	      ownPropsResolved[key] = finalValue;
90	    }
91	  }
92	
93	  return { ownPropsResolved, restProps };
94	}
95	
96	export function processUtilityProps<Keys extends string>(
97	  props: Record<string, any>,
98	  utilityPropKeys: readonly Keys[],
99	): { utilityClasses: string; utilityStyle: UtilityStyle<Keys> } {
100	  const utilityClassList: string[] = [];
101	  const generatedStyle: Record<string, unknown> = {};
102	
103	  const handleUtilityValue = (
104	    key: string,
105	    inputVal: unknown,
106	    prefix: string = '',
107	  ) => {
108	    // Get utility class configuration for this key
109	    const utilityConfig = utilityClassMap[key as keyof typeof utilityClassMap];
110	
111	    if (!utilityConfig) {
112	      // Skip if no config found for this key
113	      return;
114	    }
115	
116	    const val =
117	      'transform' in utilityConfig
118	        ? utilityConfig.transform(inputVal)
119	        : inputVal;
120	
121	    // Check if value is in the list of valid values for this utility
122	    const values = utilityConfig.values as readonly (string | number)[];
123	    if (values.length > 0 && values.includes(val as string | number)) {
124	      // Generate utility class with value suffix and optional breakpoint prefix
125	      const className = prefix
126	        ? `${prefix}${utilityConfig.class}-${val}`
127	        : `${utilityConfig.class}-${val}`;
128	      utilityClassList.push(className);
129	    } else if ('cssVar' in utilityConfig && utilityConfig.cssVar) {
130	      // Custom value - add CSS custom property AND utility class name
131	      // Only if cssVar is defined (properties with fixed values don't have cssVar)
132	      const cssVar = utilityConfig.cssVar;
133	      const cssVarKey = prefix ? `${cssVar}-${prefix.slice(0, -1)}` : cssVar;
134	      // CSS custom properties need to be set on the style object
135	      generatedStyle[cssVarKey] = val;
136	
137	      // Add utility class name (without value suffix) with optional breakpoint prefix
138	      const className = prefix
139	        ? `${prefix}${utilityConfig.class}`
140	        : utilityConfig.class;
141	      utilityClassList.push(className);
142	    }
143	    // If no cssVar and value is not in valid values, skip (invalid value for fixed-value property)
144	  };
145	
146	  for (const key of utilityPropKeys) {
147	    const value = props[key];
148	    if (value === undefined || value === null) {
149	      continue;
150	    }
151	
152	    // Check if value is a responsive object
153	    if (typeof value === 'object' && value !== null) {
154	      const breakpointValues = value as { [key: string]: unknown };
155	      // Handle responsive object values
156	      for (const bp in breakpointValues) {
157	        const prefix = bp === 'initial' ? '' : `${bp}:`;
158	        handleUtilityValue(key, breakpointValues[bp], prefix);
159	      }
160	    } else {
161	      // Handle simple value
162	      handleUtilityValue(key, value);
163	    }
164	  }
165	
166	  return {
167	    utilityClasses: utilityClassList.join(' '),
168	    utilityStyle: generatedStyle as UtilityStyle<Keys>,
169	  };
170	}
