17	import { ReactNode } from 'react';
18	import clsx from 'clsx';
19	import { useBreakpoint } from '../useBreakpoint';
20	import { useBgProvider, useBgConsumer, BgProvider } from '../useBg';
21	import { resolveDefinitionProps, processUtilityProps } from './helpers';
22	import { useAnalytics } from '../../analytics/useAnalytics';
23	import { noopTracker } from '../../analytics/useAnalytics';
24	import { useHref, useInRouterContext } from 'react-router-dom';
25	import { isExternalLink } from '../../utils/linkUtils';
26	import type {
27	  ComponentConfig,
28	  UseDefinitionOptions,
29	  UseDefinitionResult,
30	  UtilityKeys,
31	} from './types';
32	
33	export function useDefinition<
34	  D extends ComponentConfig<any, any>,
35	  P extends Record<string, any>,
36	>(
37	  definition: D,
38	  props: P,
39	  options?: UseDefinitionOptions<D>,
40	): UseDefinitionResult<D, P> {
41	  const { breakpoint } = useBreakpoint();
42	
43	  // Pre-resolve href at component render time (where route context is
44	  // correct), so that click-navigation has a correct absolute path
45	  // regardless of where useNavigate is called. `useHref` returns the
46	  // path with basename prepended; strip it so the output is the
47	  // canonical pre-basename form that react-router's downstream useHref
48	  // and navigate both expect as input (avoids double-prefixing).
49	  // External URLs bypass resolution.
50	  let hrefResolvedProps = props;
51	  const hasRouter = useInRouterContext();
52	  if (hasRouter) {
53	    const rawHref = (props as any).href;
54	    // useHref('/') returns the router's basename. Strip trailing slashes
55	    // so the prefix check works regardless of how the consumer configured
56	    // their <Router basename>.
57	    const basename = useHref('/').replace(/\/+$/, '') || '/';
58	    const absoluteHref = useHref(rawHref ?? '');
59	    if (rawHref !== undefined && !isExternalLink(rawHref)) {
60	      let stripped = absoluteHref;
61	      if (
62	        basename !== '/' &&
63	        (absoluteHref === basename || absoluteHref.startsWith(`${basename}/`))
64	      ) {
65	        stripped =
66	          absoluteHref === basename ? '/' : absoluteHref.slice(basename.length);
67	      }
68	      hrefResolvedProps = { ...props, href: stripped } as P;
69	    }
70	  }
71	
72	  // Resolve all props centrally — applies responsive values and defaults
73	  const { ownPropsResolved, restProps } = resolveDefinitionProps(
74	    definition,
75	    hrefResolvedProps,
76	    breakpoint,
77	  );
78	
79	  const dataAttributes: Record<string, string | undefined> = {};
80	
81	  for (const [key, config] of Object.entries(definition.propDefs)) {
82	    const finalValue = ownPropsResolved[key];
83	
84	    if (finalValue !== undefined) {
85	      // Skip data-bg for bg prop when the provider path handles it
86	      if (key === 'bg' && definition.bg === 'provider') continue;
87	
88	      if ((config as any).dataAttribute) {
89	        // eslint-disable-next-line no-restricted-syntax
90	        dataAttributes[`data-${key.toLowerCase()}`] = String(finalValue);
91	      }
92	    }
93	  }
94	
95	  // Provider: resolve bg and provide context for children
96	  const providerBg = useBgProvider(
97	    definition.bg === 'provider' ? ownPropsResolved.bg : undefined,
98	  );
99	
100	  // Consumer: read parent context bg
101	  const consumerBg = useBgConsumer();
102	
103	  // Provider: set data-bg from the resolved provider bg
104	  if (definition.bg === 'provider' && providerBg.bg !== undefined) {
105	    dataAttributes['data-bg'] = String(providerBg.bg);
106	  }
107	
108	  // Consumer: set data-on-bg from the parent context
109	  if (definition.bg === 'consumer' && consumerBg.bg !== undefined) {
110	    dataAttributes['data-on-bg'] = String(consumerBg.bg);
111	  }
112	
113	  const { utilityClasses, utilityStyle } = processUtilityProps<UtilityKeys<D>>(
114	    props,
115	    (definition.utilityProps ?? []) as readonly UtilityKeys<D>[],
116	  );
117	
118	  // Analytics: conditionally call useAnalytics based on definition flag
119	  let analytics = noopTracker;
120	  if (definition.analytics) {
121	    const tracker = useAnalytics();
122	    analytics = ownPropsResolved.noTrack ? noopTracker : tracker;
123	  }
124	
125	  const utilityTarget = options?.utilityTarget ?? 'root';
126	  const classNameTarget = options?.classNameTarget ?? 'root';
127	
128	  const classes: Record<string, string> = {};
129	
130	  for (const [name, cssKey] of Object.entries(definition.classNames)) {
131	    classes[name] = clsx(
132	      cssKey as string,
133	      definition.styles[cssKey as keyof typeof definition.styles],
134	      utilityTarget === name && utilityClasses,
135	      classNameTarget === name && ownPropsResolved.className,
136	    );
137	  }
138	
139	  let children: ReactNode | undefined;
140	  let childrenWithBgProvider: ReactNode | undefined;
141	
142	  if (definition.bg === 'provider') {
143	    childrenWithBgProvider = providerBg.bg ? (
144	      <BgProvider bg={providerBg.bg}>{props.children}</BgProvider>
145	    ) : (
146	      props.children
147	    );
148	  } else {
149	    children = props.children;
150	  }
151	
152	  return {
153	    ownProps: {
154	      classes,
155	      ...ownPropsResolved,
156	      ...(definition.bg === 'provider'
157	        ? { childrenWithBgProvider }
158	        : { children }),
159	    },
160	    restProps,
161	    dataAttributes,
162	    utilityStyle,
163	    ...(definition.analytics ? { analytics } : {}),
164	  } as unknown as UseDefinitionResult<D, P>;
165	}
