17	import type { ReactNode } from 'react';
18	import type { Responsive } from '../../types';
19	import type { AnalyticsTracker } from '../../analytics/types';
20	import type { utilityClassMap } from '../../utils/utilityClassMap';
21	
22	export type UnwrapResponsive<T> = T extends Responsive<infer U> ? U : T;
23	
24	export interface PropDefConfig<T> {
25	  dataAttribute?: boolean;
26	  default?: UnwrapResponsive<T>;
27	}
28	
29	export type UtilityPropKey = keyof typeof utilityClassMap;
30	
31	export interface ComponentConfig<
32	  P extends Record<string, any>,
33	  S extends Record<string, string>,
34	> {
35	  styles: S;
36	  classNames: Record<string, keyof S>;
37	  propDefs: { [K in keyof P]: PropDefConfig<P[K]> };
38	  // readonly for compatibility with const inference from factory
39	  utilityProps?: readonly UtilityPropKey[];
40	  /**
41	   * How this component participates in the bg system.
42	   *
43	   * - `'provider'` — calls `useBgProvider`, sets `data-bg`, wraps children in `BgProvider`
44	   * - `'consumer'` — calls `useBgConsumer`, sets `data-on-bg`
45	   */
46	  bg?: 'provider' | 'consumer';
47	  /**
48	   * Whether this component fires analytics events.
49	   * When true, `useDefinition` will call `useAnalytics()` and return
50	   * an `analytics` tracker. The component's own props type must include
51	   * `noTrack?: boolean`.
52	   */
53	  analytics?: boolean;
54	}
55	
56	/**
57	 * Type constraint that validates bg props are present in the props type.
58	 * - Provider components must include 'bg' in their props and 'children' in propDefs
59	 * - Consumer components don't need a bg prop
60	 */
61	export type BgPropsConstraint<P, Bg> = Bg extends 'provider'
62	  ? 'bg' extends keyof P
63	    ? 'children' extends keyof P
64	      ? {} extends Pick<P, 'children'>
65	        ? {
66	            __error: 'Bg provider components cannot have children as optional.';
67	          }
68	        : {}
69	      : {
70	          __error: 'Bg provider components must include children in own props type.';
71	        }
72	    : {
73	        __error: 'Bg provider components must include bg in own props type.';
74	      }
75	  : {};
76	
77	/**
78	 * Type constraint that validates analytics props are present in the props type.
79	 * Components with analytics: true must include 'noTrack' in their props.
80	 */
81	export type AnalyticsPropsConstraint<P, Analytics> = Analytics extends true
82	  ? 'noTrack' extends keyof P
83	    ? {}
84	    : {
85	        __error: 'Analytics components must include noTrack in own props type.';
86	      }
87	  : {};
88	
89	export interface UseDefinitionOptions<D extends ComponentConfig<any, any>> {
90	  utilityTarget?: keyof D['classNames'] | null;
91	  classNameTarget?: keyof D['classNames'] | null;
92	}
93	
94	// Resolve prop type: unwrap Responsive, make non-nullable if default exists
95	// Uses "inverse check" pattern: check if undefined is assignable to the default type
96	type ResolvePropType<
97	  T,
98	  Config extends PropDefConfig<any>,
99	> = undefined extends Config['default']
100	  ? UnwrapResponsive<T> // Default is missing/undefined -> keep original type
101	  : Exclude<UnwrapResponsive<T>, undefined>; // Default exists -> remove undefined
102	
103	// Build ownProps shape from propDefs
104	// Iterates over PropDefs keys (not P keys) to preserve literal config types
105	type ResolvedOwnProps<
106	  P,
107	  PropDefs extends Record<string, PropDefConfig<any>>,
108	> = {
109	  [K in keyof PropDefs & keyof P]: ResolvePropType<P[K], PropDefs[K]>;
110	};
111	
112	type BaseOwnProps<
113	  D extends ComponentConfig<any, any>,
114	  P extends Record<string, any>,
115	> = {
116	  classes: Record<keyof D['classNames'], string>;
117	} & ResolvedOwnProps<P, D['propDefs']>;
118	
119	type ResolveBgProps<
120	  D extends ComponentConfig<any, any>,
121	  TBase,
122	> = D['bg'] extends 'provider'
123	  ? Omit<TBase, 'children'> & { childrenWithBgProvider: ReactNode }
124	  : TBase;
125	
126	type DataAttributeKeys<PropDefs> = {
127	  [K in keyof PropDefs]: PropDefs[K] extends { dataAttribute: true }
128	    ? K
129	    : never;
130	}[keyof PropDefs];
131	
132	type DataAttributes<PropDefs> = {
133	  [K in DataAttributeKeys<PropDefs> as `data-${Lowercase<
134	    string & K
135	  >}`]?: string;
136	} & { 'data-bg'?: string; 'data-on-bg'?: string };
137	
138	export type UtilityKeys<D extends ComponentConfig<any, any>> =
139	  D['utilityProps'] extends ReadonlyArray<infer K extends string> ? K : never;
140	
141	type UtilityMapType = typeof utilityClassMap;
142	
143	// Extract CSS variable key for a given prop (e.g., 'p' -> '--p')
144	type GetCssVarKey<K> = K extends keyof UtilityMapType
145	  ? UtilityMapType[K] extends { cssVar: infer V extends string }
146	    ? V
147	    : never
148	  : never;
149	
150	export type UtilityStyle<Keys extends string> = {
151	  [K in Keys as GetCssVarKey<K>]?: string | number;
152	};
153	
154	type ResolvedUtilityStyle<D extends ComponentConfig<any, any>> = UtilityStyle<
155	  UtilityKeys<D>
156	>;
157	
158	export type UseDefinitionResult<
159	  D extends ComponentConfig<any, any>,
160	  P extends Record<string, any>,
161	> = {
162	  ownProps: ResolveBgProps<D, BaseOwnProps<D, P>>;
163	
164	  // Rest props excludes both propDefs keys AND utility prop keys
165	  restProps: keyof Omit<P, keyof D['propDefs'] | UtilityKeys<D>> extends never
166	    ? Record<string, never>
167	    : Omit<P, keyof D['propDefs'] | UtilityKeys<D>>;
168	
169	  dataAttributes: DataAttributes<D['propDefs']>;
170	
171	  utilityStyle: ResolvedUtilityStyle<D>;
172	} & (D['analytics'] extends true ? { analytics: AnalyticsTracker } : {});
